query newsLeagues($limit: Int) {
  viewer {
    id
    ... on Member {
      leagues {
        id
        slug
        name
        __typename
      }
      __typename
    }
    ... on ExternalStaff {
      leagues {
        id
        slug
        name
        __typename
      }
      __typename
    }
    __typename
  }
  national: league(id: 589) {
    id
    name
    slug
    news(limit: $limit) {
      id
      __typename
    }
    __typename
  }
}
